        });
      });
      loadCount++;
      if (start + 3 >= moreArticles.length) {
        document.getElementById('loadMoreBtn').textContent = 'No More Articles';
        document.getElementById('loadMoreBtn').disabled = true;
        document.getElementById('loadMoreBtn').style.opacity = '0.5';
